<template>
  <main class="ppt-studio">
    <nav class="studio-nav"><button class="brand" @click="router.push('/dashboard')"><i>D</i><span><b>Dokiai Academic</b><small>AI PRESENTATION STUDIO</small></span></button><div><span>Academic AI</span><button @click="router.push('/dashboard')">返回工作台</button></div></nav>
    <header class="hero"><div class="eyebrow"><i></i>DOKIAI PPT WORKFLOW</div><h1>让论文自动变成<br><em>专业答辩 PPT</em></h1><p>AI 理解论文结构，提炼答辩逻辑，自动生成可编辑 PPTX。</p><div class="hero-actions"><button class="primary" @click="scrollToUpload">开始生成 PPT　→</button><button class="secondary" @click="showFlow=!showFlow">查看生成流程　⌄</button></div><div class="support"><span>支持格式</span><b>PPTX</b><b>DOCX</b><b>PDF</b></div><i class="orb one"></i><i class="orb two"></i></header>

    <section v-if="stage==='upload'" ref="uploadSection" class="start-grid">
      <article class="glass upload-card"><header><div><small>STEP 01 · SOURCE FILE</small><h2>上传完整源文件</h2></div><span class="chip">AI READY</span></header><label class="drop-zone" :class="{selected:file}" @dragover.prevent @drop.prevent="onDrop"><input type="file" accept=".pptx,.docx,.pdf" @change="selectFile"><span class="upload-icon">↑</span><template v-if="!file"><strong>拖入论文或项目文档</strong><p>或点击选择本地文件 · 最大 80 MB</p><div><b>PPTX</b><b>DOCX</b><b>PDF</b></div></template><template v-else><span class="file-type">{{ fileExt }}</span><strong>{{ file.name }}</strong><p>{{ formatBytes(file.size) }} · 已准备解析</p><button type="button" @click.prevent="file=null">重新选择</button></template></label><div class="recognition"><span>AI 自动识别</span><ul><li>✓ 章节结构</li><li>✓ 图片素材</li><li>✓ 表格数据</li><li>✓ 答辩重点</li></ul></div></article>
      <article class="glass info-card"><header><div><small>PROJECT PROFILE</small><h2>项目资料确认</h2></div><button class="detect" :disabled="!file" @click="autoHint">✦ AI 自动识别</button></header><div class="detect-state"><i>✦</i><span><b>{{ file?'文档已就绪':'等待 AI 读取' }}</b><small>{{ file?'上传后将自动提取题目、作者与专业信息':'选择完整文档后自动识别，无需逐项填写' }}</small></span></div><div class="form-grid"><label class="wide"><span>论文题目 <small>AI 可识别</small></span><input v-model="form.topic" placeholder="上传后自动提取"></label><label><span>汇报人</span><input v-model="form.presenter" placeholder="AI 自动提取"></label><label><span>专业</span><input v-model="form.major" placeholder="AI 自动提取"></label><label><span>指导教师</span><input v-model="form.advisor" placeholder="AI 自动提取"></label><label><span>学号</span><input v-model="form.studentNumber" placeholder="AI 自动提取"></label></div><button class="generate" :disabled="!file||busy" @click="start"><span>✦</span>{{ busy?'AI 正在启动工作流':'开始智能生成' }}<b>→</b></button><p class="safe-note">文档仅用于本次内容分析与 PPT 生成</p></article>
    </section>

    <section v-else class="workflow-center">
      <article class="glass task-card" :class="{failed:stage==='error',complete:stage==='done'}"><div class="task-icon"><span v-if="stage==='done'">✓</span><span v-else-if="stage==='error'">!</span><i v-else></i></div><div><small>{{ stage==='done'?'GENERATION COMPLETE':stage==='error'?'TASK INTERRUPTED':'AI IS WORKING' }}</small><h2>{{ taskTitle }}</h2><p>{{ taskDescription }}</p></div><strong>{{ displayProgress }}<small>%</small></strong><div class="master-progress"><i :style="{width:displayProgress+'%'}"></i></div><footer><span>当前步骤：<b>{{ activeStepLabel }}</b></span><span>当前页面：<b>{{ currentPage }}/{{ totalPages }}</b></span><span>任务 ID：<b>{{ shortId }}</b></span></footer></article>
      <article class="glass flow-card"><header><div><small>LIVE WORKFLOW</small><h2>AI PPT 生成流程</h2></div><span>{{ completedStepCount }}/6 已完成</span></header><div class="steps"><div v-for="item in workflowSteps" :key="item.no" :class="item.state"><span><i v-if="item.state==='done'">✓</i><b v-else>{{ item.no }}</b></span><div><small>STEP {{ item.no }}</small><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div><em>{{ stateLabel(item.state) }}</em></div></div></article>
      <div class="workflow-grid"><article class="glass analysis-card"><header><div><small>DOCUMENT INSIGHTS</small><h2>文档识别结果</h2></div><span class="success-dot">识别完成</span></header><div class="metrics"><span><i>章</i><b>{{ analysis.precheck?.validChapterCount||analysis.headings?.length||0 }}</b><small>有效章节</small></span><span><i>图</i><b>{{ analysis.validImageCount||analysis.imageCount||0 }}</b><small>有效图片</small></span><span><i>表</i><b>{{ analysis.tableCount||0 }}</b><small>数据表格</small></span></div><p>{{ analysis.precheck?.message||'AI 正在建立论文内容索引' }}</p></article><article class="glass log-card"><header><div><small>PROCESS LOG</small><h2>生成过程日志</h2></div><button @click="logsOpen=!logsOpen">{{ logsOpen?'收起':'展开全部' }}⌄</button></header><ul><li v-for="(log,i) in visibleLogs" :key="i"><i :class="log.type">{{ log.type==='doing'?'↻':log.type==='error'?'!':'✓' }}</i><span>{{ log.text }}</span><time>{{ log.time }}</time></li></ul></article></div>
      <article v-if="stage==='done'" class="glass result-card"><div class="result-mark">✓</div><div><small>PRESENTATION READY</small><h2>PPT 生成完成</h2><p>文字、图片和表格均保持独立可编辑。</p></div><div class="result-stats"><span><b>{{ totalPages }}</b>页</span><span><b>{{ resultSize }}</b>文件大小</span><span><b>{{ elapsedText }}</b>生成耗时</span></div><div class="result-actions"><button class="secondary" @click="preview">预览 PPT</button><button class="primary" @click="download">下载 PPTX ↓</button><button class="text-button" @click="reset">重新生成</button></div></article>
      <article v-if="stage==='error'" class="glass error-card"><span>!</span><div><small>AI TASK EXCEPTION</small><h2>任务在「{{ activeStepLabel }}」阶段中断</h2><p>{{ errorMessage }}</p></div><button class="secondary" @click="resume">重新执行当前步骤</button><button class="primary" @click="reset">重新生成</button></article>
    </section>
    <section v-if="showFlow&&stage==='upload'" class="flow-preview glass"><small>HOW IT WORKS</small><h2>从论文到答辩 PPT，只需一次上传</h2><div><span v-for="item in workflowSteps" :key="item.no"><b>{{ item.no }}</b><strong>{{ item.title }}</strong><small>{{ item.description }}</small></span></div></section>
  </main>
</template>

<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { createPptProject,getPptProject,uploadPptSource,analyzePptProject,generatePptOutline,savePptOutline,planPptSlides,generatePptFile,getPptProgress,downloadPptFile } from '../../api/rewrite';
const router=useRouter(),route=useRoute(),uploadSection=ref(null),stage=ref('upload'),busy=ref(false),file=ref(null),project=ref({progress:0}),analysis=ref({}),outline=ref([]),pages=ref([]),activeStep=ref(0),logs=ref([]),logsOpen=ref(false),showFlow=ref(false),errorMessage=ref(''),startedAt=ref(0),elapsed=ref(0),resultBytes=ref(0);const form=ref({topic:'',presenter:'',major:'',advisor:'',studentNumber:'',targetSlideCount:16});const stepData=[['01','文件解析','正在读取章节结构和文档内容'],['02','内容理解','AI 正在提炼答辩重点'],['03','页面规划','生成 PPT 页面结构'],['04','素材绑定','匹配图片和表格资源'],['05','智能排版','生成页面布局'],['06','PPT 生成','正在输出可编辑 PPTX']];
const workflowSteps=computed(()=>stepData.map((x,i)=>({no:x[0],title:x[1],description:x[2],state:stage.value==='done'||i<activeStep.value?'done':stage.value==='error'&&i===activeStep.value?'error':i===activeStep.value?'active':'waiting'}))),cleanTopic=computed(()=>String(project.value.topic||form.value.topic||'未命名学术答辩').replace(/[\\/:*?"<>|]/g,'_')),fileExt=computed(()=>file.value?.name.split('.').pop()?.toUpperCase()||'FILE'),displayProgress=computed(()=>stage.value==='done'?100:stage.value==='error'?Number(project.value.progress||activeStep.value*16):Math.max(Number(project.value.progress||0),Math.min(95,activeStep.value*16+8))),totalPages=computed(()=>Math.max(1,pages.value.length+3)),completedPages=computed(()=>pages.value.filter(x=>x.status==='SUCCESS').length),currentPage=computed(()=>stage.value==='done'?totalPages.value:Math.min(totalPages.value,Math.max(1,completedPages.value+1))),completedStepCount=computed(()=>workflowSteps.value.filter(x=>x.state==='done').length),activeStepLabel=computed(()=>stepData[Math.min(activeStep.value,5)][1]),shortId=computed(()=>String(project.value.id||'PREPARING').slice(0,8).toUpperCase()),taskTitle=computed(()=>stage.value==='done'?'你的答辩 PPT 已准备好':stage.value==='error'?'AI 任务需要处理':`正在进行${activeStepLabel.value}`),taskDescription=computed(()=>stage.value==='done'?'已完成内容规划、素材绑定与可编辑 PPTX 输出。':stage.value==='error'?errorMessage.value:stepData[Math.min(activeStep.value,5)][2]),visibleLogs=computed(()=>logsOpen.value?logs.value:logs.value.slice(-3)),resultSize=computed(()=>resultBytes.value?formatBytes(resultBytes.value):'生成完成'),elapsedText=computed(()=>elapsed.value?`${(elapsed.value/1000).toFixed(1)}秒`:'已完成');
function formatBytes(n){return n>1048576?(n/1048576).toFixed(2)+' MB':Math.max(1,n/1024).toFixed(1)+' KB'}function stateLabel(v){return({done:'完成',active:'处理中',waiting:'等待',error:'异常'})[v]}function now(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}function addLog(text,type='done'){logs.value.push({text,type,time:now()})}function nextStep(index,text){activeStep.value=index;addLog(text,index===5?'doing':'done')}function scrollToUpload(){uploadSection.value?.scrollIntoView({behavior:'smooth',block:'center'})}function selectFile(e){file.value=e.target.files?.[0]||null}function onDrop(e){file.value=e.dataTransfer.files?.[0]||null}function autoHint(){ElMessage.success('上传后将自动识别并回填项目信息')}function tick(){return new Promise(r=>setTimeout(r,120))}
async function start(){busy.value=true;stage.value='running';startedAt.value=Date.now();logs.value=[];errorMessage.value='';try{nextStep(0,'正在上传并读取完整源文件');project.value=await createPptProject(form.value);project.value=await uploadPptSource(project.value.id,file.value);project.value=await analyzePptProject(project.value.id);analysis.value=JSON.parse(project.value.analysis_json||'{}');Object.assign(form.value,{topic:project.value.topic||form.value.topic,presenter:project.value.presenter||form.value.presenter,major:project.value.major||form.value.major,advisor:project.value.advisor||form.value.advisor,studentNumber:project.value.student_number||form.value.studentNumber});addLog(`已解析 ${analysis.value.precheck?.validChapterCount||analysis.value.headings?.length||0} 个章节`);nextStep(1,'AI 正在提炼答辩重点');const out=await generatePptOutline(project.value.id);project.value=out;outline.value=out.outline||[];addLog('已完成答辩内容理解');nextStep(2,'正在生成 PPT 页面结构');await saveOutlineOnly(false);const planned=await planPptSlides(project.value.id);project.value=planned;pages.value=planned.slides||[];addLog(`已规划 ${pages.value.length+3} 页演示内容`);nextStep(3,'正在匹配图片和表格资源');addLog(`已识别 ${analysis.value.validImageCount||analysis.value.imageCount||0} 张有效图片`);await tick();nextStep(4,'正在生成页面布局');await tick();nextStep(5,'正在输出可编辑 PPTX');await generatePptFile(project.value.id);project.value=await getPptProgress(project.value.id);pages.value=project.value.slides||pages.value;elapsed.value=Date.now()-startedAt.value;addLog('可编辑 PPTX 已生成');stage.value='done'}catch(e){errorMessage.value=e?.responseData?.message||e.message||'生成任务暂时中断';addLog(errorMessage.value,'error');stage.value='error'}finally{busy.value=false}}
async function saveOutlineOnly(notify=true){const data=await savePptOutline(project.value.id,outline.value.map((x,i)=>({id:x.id,title:x.title,description:x.description||'',targetSlides:Math.min(2,Math.max(1,x.target_slides||1)),sectionOrder:i+1})));outline.value=data.outline||outline.value;if(notify)ElMessage.success('页面规划已保存')}async function getBlob(){const blob=await downloadPptFile(project.value.id);resultBytes.value=blob.size;return blob}async function download(){const blob=await getBlob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=cleanTopic.value+'.pptx';a.click();URL.revokeObjectURL(url)}async function preview(){const blob=await getBlob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}function reset(){stage.value='upload';project.value={progress:0};analysis.value={};outline.value=[];pages.value=[];logs.value=[];activeStep.value=0;file.value=null}function resume(){file.value?start():reset()}
onMounted(async()=>{if(!route.query.projectId)return;try{const data=await getPptProject(route.query.projectId);project.value=data;outline.value=data.outline||[];pages.value=data.slides||[];analysis.value=JSON.parse(data.analysis_json||'{}');stage.value=data.status==='SUCCESS'?'done':data.status==='FAILED'?'error':data.status==='DRAFT'?'upload':'running';activeStep.value=data.status==='SUCCESS'?5:Math.min(5,Math.floor(Number(data.progress||0)/17))}catch(e){ElMessage.warning('项目无法恢复')}});
</script>

